const categories=foodNames.map((_,i)=>[6,25,26,27,28,29].includes(i)?'디저트':[1,9,11,19,20,21,22].includes(i)?'간식':'식사');
let state;try{state=JSON.parse(localStorage.getItem('kansai-state'))}catch{}if(!state||typeof state!=='object'||Array.isArray(state))state={};for(const k of ['done','food','times','notes'])if(!state[k]||typeof state[k]!=='object')state[k]={};
if(!Array.isArray(state.packing))state.packing=['여권','휴대폰','충전기·케이블','보조배터리','일본용 변환 플러그','Suica 충전','엔화·결제 카드','eSIM·로밍 준비','여행자보험 확인','속옷·양말','여벌 옷','편한 신발','세면도구','상비약','우산','HARUKA·스카이빌딩 티켓 저장'].map((name,i)=>({id:'base-'+i,name,done:false}));
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const map=q=>'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(q);
const dates=['2026-10-10','2026-10-11','2026-10-12','2026-10-13'];function dateJP(){const p=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(t=>p.find(x=>x.type===t).value).join('-')}function tripDay(date){return date<dates[0]?0:date>dates[3]?3:Math.max(0,dates.indexOf(date))}
let lastDate=dateJP(),day=tripDay(lastDate),manualDay=false,tab=lastDate<dates[0]?'packing':'today',foodFilter='전체',ticketURL=null;
const save=()=>{try{localStorage.setItem('kansai-state',JSON.stringify(state));return true}catch{alert('저장에 실패했습니다. 브라우저 저장 공간을 확인하세요.');return false}};$('#home').href=map(HOME);
const key=(d,i)=>d+'-'+i;const time=(d,i)=>state.times[key(d,i)]||plans[d].items[i][0];
function pixelIcon(index){return window.foodPixelArt(index,foodNames[index])}
function stageCards(){return `<div class="stage-grid">${plans.map((p,d)=>`<button data-day="${d}" aria-pressed="${d===day}" class="stage stage-${d} ${d===day?'selected':''}"><small>STAGE ${d+1}</small><strong>${p.city}</strong><span>10.${10+d}</span></button>`).join('')}</div>`}
function card(d,i){const it=plans[d].items[i],k=key(d,i);return `<article class="quest-row ${state.done[k]?'done':''}"><div class="time">${esc(time(d,i))}<span>${state.done[k]?'✓':'◇'}</span></div><div class="grow"><h3>${esc(it[1])}</h3><p>${esc(it[3])}</p><div class="row-actions"><a class="action" href="${map(it[2])}" target="_blank" rel="noopener">길찾기 ↗</a><button class="action secondary" data-done="${k}" aria-pressed="${!!state.done[k]}">${state.done[k]?'CLEAR · 취소':'완료 체크'}</button><details id="edit-${k}"><summary>시각 수정</summary><input aria-label="${esc(it[1])} 계획 시각" type="time" value="${esc(time(d,i))}" data-time="${k}"></details></div></div></article>`}
function packing(){const count=state.packing.filter(p=>p.done).length;return `<div class="section-heading"><small>BEFORE THE ADVENTURE</small><h2>모험의 준비물</h2><p>${count} / ${state.packing.length} 준비 완료 · 이 기기에 저장</p></div><div class="panel"><form id="pack-form"><label class="sr-only" for="pack-name">준비물 이름</label><input id="pack-name" maxlength="80" placeholder="추가로 챙길 준비물" required><button class="action" type="submit">+ 추가</button></form><div class="pack-list">${state.packing.map(p=>`<div class="pack-row"><label><input type="checkbox" data-pack="${esc(p.id)}" ${p.done?'checked':''}><span>${esc(p.name)}</span></label><button class="delete-small" data-pack-delete="${esc(p.id)}" aria-label="${esc(p.name)} 삭제">×</button></div>`).join('')}</div></div>`}
function render(){const active=document.activeElement;const attr=['data-day','data-done','data-food','data-time','data-pack','data-filter'].find(a=>active?.hasAttribute(a));const focus=attr?'['+attr+'="'+active.getAttribute(attr)+'"]':null;const open=[...document.querySelectorAll('#content details[open]')].map(e=>e.id);$('#days').hidden=tab!=='today';$('#days').innerHTML=tab==='today'?stageCards():'';document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',String(b.dataset.tab===tab))});const p=plans[day];let html='';if(tab==='packing')html=packing();
if(tab==='today'){const n=p.items.findIndex((_,i)=>!state.done[key(day,i)]),count=p.items.filter((_,i)=>state.done[key(day,i)]).length;html=`<div class="section-heading"><small>STAGE ${day+1} · ${p.city}</small><h2>${p.theme}</h2><p>${lastDate<dates[0]?'여행 준비 · 일정 미리보기':lastDate>dates[3]?'여행 기록':'일본 시간 기준'} · 수정 가능한 계획 시각</p></div><div class="panel next"><small>${n<0?'STAGE CLEAR!':'NEXT QUEST'}</small><h2>${n<0?'오늘의 모험 완료!':esc(p.items[n][1])}</h2><p>${n<0?'오늘의 기억을 메모해 주세요.':esc(time(day,n))+' 예정 · 첫 미완료 일정'}</p>${n<0?'':`<a class="action" href="${map(p.items[n][2])}" target="_blank" rel="noopener">길찾기 시작 ↗</a>`}<div class="progress-line"><span>${count} / ${p.items.length} CLEAR</span><div class="progress" role="progressbar" aria-label="일정 완료" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${p.items.length}"><i style="width:${100*count/p.items.length}%"></i></div></div></div><div class="panel timeline">${p.items.map((_,i)=>card(day,i)).join('')}</div><div class="panel"><h3>모험의 기록</h3><textarea id="note" aria-label="오늘의 메모" placeholder="락커 위치, 예약, 오늘의 기억…">${esc(state.notes[day]||'')}</textarea></div>`}
if(tab==='all')html=`<div class="section-heading"><small>WORLD MAP</small><h2>네 개의 스테이지</h2><p>도시를 선택하면 아래에 상세 일정이 표시됩니다.</p></div>${stageCards()}<section id="stage-detail" class="panel timeline" aria-label="${p.city} 상세 일정"><div class="detail-heading"><small>10.${10+day} · STAGE ${day+1}</small><h2>${p.city}</h2><p>${p.theme}</p></div>${p.items.map((_,i)=>card(day,i)).join('')}</section>`;
if(tab==='food'){html=`<div class="section-heading"><small>FOOD COLLECTION</small><h2>간사이 맛 도감</h2><p>${foodNames.filter((_,i)=>state.food[i]).length} / ${foodNames.length} 맛보기 완료 · 픽셀 일러스트</p></div><div class="filters">${['전체','식사','간식','디저트'].map(f=>`<button data-filter="${f}" aria-pressed="${foodFilter===f}" class="${foodFilter===f?'selected':''}">${f}</button>`).join('')}</div><div class="food-grid">${foodNames.map((f,i)=>foodFilter!=='전체'&&categories[i]!==foodFilter?'':`<article class="food-card ${state.food[i]?'collected':''}"><button class="food-art" data-food-info="${i}" aria-label="${f} 설명 보기">${pixelIcon(i)}<span>${state.food[i]?'GET!':categories[i]}</span></button><h3>${f}</h3><p>${descriptions[i]}</p><label class="food-check"><input type="checkbox" data-food="${i}" ${state.food[i]?'checked':''}>${state.food[i]?'맛봤어요!':'먹어보기'}</label></article>`).join('')}</div>`}
if(tab==='tickets')html=`<div class="section-heading"><small>ITEM INVENTORY</small><h2>티켓 보관함</h2><p>구매한 티켓 이미지를 등록해 주세요.</p></div>`+['HARUKA','우메다 스카이빌딩'].map((t,i)=>`<article class="panel ticket-card"><small>ITEM 0${i+1}</small><h3>${t}</h3><p id="status-${i}" role="status">저장 상태 확인 중…</p><input aria-label="${t} 이미지 등록" type="file" accept="image/*" data-upload="${i}"><button class="action" data-view="${i}" disabled>티켓 열기</button><button class="action secondary" data-delete="${i}" hidden>이미지 삭제</button></article>`).join('')+'<p class="notice">이미지는 이 기기에만 저장됩니다. 브라우저 데이터를 지우면 삭제되며, 다른 기기와 동기화되지 않습니다.</p>';
$('#content').innerHTML=html;open.forEach(id=>{const e=document.getElementById(id);if(e)e.open=true});if(focus)$(focus)?.focus({preventScroll:true});if(tab==='tickets')refreshTickets();}
document.addEventListener('submit',e=>{if(e.target.id!=='pack-form')return;e.preventDefault();const name=$('#pack-name').value.trim();if(!name)return;state.packing.push({id:'custom-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),name,done:false});save();render();$('#pack-name').focus()});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.day!==undefined){day=Number(d.day);manualDay=true;render();if(tab==='all')$('#stage-detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}if(d.tab){tab=d.tab;if(tab==='today'){manualDay=false;day=tripDay(dateJP())}render();window.scrollTo({top:0,behavior:'auto'})}if(d.done){state.done[d.done]=!state.done[d.done];save();render()}if(d.filter){foodFilter=d.filter;render()}if(d.packDelete){const index=state.packing.findIndex(p=>p.id===d.packDelete);if(index>=0&&confirm('이 준비물 항목을 삭제할까요?')){state.packing.splice(index,1);save();render();$('#pack-name').focus()}}if(d.foodInfo!==undefined){const i=Number(d.foodInfo);const photo=window.foodPhotos[i];$('#food-detail-content').innerHTML=`<div class="food-detail-heading">${pixelIcon(i)}<div><h2>${foodNames[i]}</h2><p>${descriptions[i]}</p></div></div><figure class="real-food"><img src="${esc(photo.src)}" alt="${esc(foodNames[i])} 실제 음식 사진" width="640" decoding="async"><figcaption>사진: ${esc(photo.author)} · <a href="${esc(photo.source)}" target="_blank" rel="noopener">출처</a> · <a href="${esc(photo.licenseUrl || photo.source)}" target="_blank" rel="noopener">${esc(photo.license)}</a></figcaption></figure>`;$('#food-dialog').showModal()}if(d.view!==undefined){try{const blob=await ticket('get',d.view);if(!blob){alert('먼저 티켓 이미지를 등록하세요.');return}if(ticketURL)URL.revokeObjectURL(ticketURL);ticketURL=URL.createObjectURL(blob);$('#ticket-image').src=ticketURL;$('#viewer').showModal()}catch{alert('티켓을 불러올 수 없습니다. 원본 예약 앱을 확인하세요.')}}if(d.delete!==undefined&&confirm('저장한 티켓 이미지를 삭제할까요?')){try{await ticket('delete',d.delete);await refreshTickets()}catch{alert('티켓 삭제 실패 · 다시 시도하세요.');await refreshTickets()}}});
document.addEventListener('change',async e=>{const t=e.target,d=t.dataset;if(d.food!==undefined){state.food[d.food]=t.checked;save();render();if(t.checked){const art=$('[data-food-info="'+d.food+'"]');art?.classList.add('get-animation')}}if(d.pack){const item=state.packing.find(p=>p.id===d.pack);if(item){item.done=t.checked;save();render()}}if(d.time){if(t.value)state.times[d.time]=t.value;else delete state.times[d.time];save();render()}if(d.upload!==undefined&&t.files[0]){const f=t.files[0];if(!f.type.startsWith('image/')){alert('이미지 파일을 선택하세요.');return}if(f.size>15*1024*1024){alert('15MB 이하 이미지를 선택하세요.');return}try{await ticket('put',d.upload,f);await refreshTickets()}catch{alert('이미지 저장 실패 · 브라우저 저장 공간을 확인하세요.')}}});
document.addEventListener('input',e=>{if(e.target.id==='note'){state.notes[day]=e.target.value;save()}});$('#close').onclick=()=>$('#viewer').close();$('#food-close').onclick=()=>$('#food-dialog').close();$('#viewer').addEventListener('close',()=>{if(ticketURL){URL.revokeObjectURL(ticketURL);ticketURL=null;$('#ticket-image').removeAttribute('src')}});
function ticket(op,id,value){return new Promise((resolve,reject)=>{const r=indexedDB.open('kansai-tickets',1);r.onupgradeneeded=()=>r.result.createObjectStore('images');r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('저장소 사용 중'));r.onsuccess=()=>{const db=r.result;try{const tx=db.transaction('images',op==='get'?'readonly':'readwrite'),s=tx.objectStore('images');const q=op==='put'?s.put(value,id):op==='delete'?s.delete(id):s.get(id);let result;q.onsuccess=()=>result=q.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onabort=tx.onerror=()=>{db.close();reject(tx.error||new Error('저장 중단'))}}catch(error){db.close();reject(error)}}})}
async function refreshTickets(){for(let i=0;i<2;i++){try{const blob=await ticket('get',String(i));const el=$('#status-'+i);if(el){el.textContent=blob?'이 기기에 저장됨':'이미지 미등록';const view=$('[data-view="'+i+'"]'),del=$('[data-delete="'+i+'"]');if(view)view.disabled=!blob;if(del)del.hidden=!blob}}catch{const el=$('#status-'+i);if(el)el.textContent='저장소를 사용할 수 없습니다.'}}}
function tick(){const date=dateJP();if(date!==lastDate){lastDate=date;if(!manualDay)day=tripDay(date);render()}$('#clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' JST'}tick();setInterval(tick,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
